  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "星星为什么在闪耀呢"
        },
        {
          "id": "C1-02",
          "zh": "云儿为什么在天空游荡"
        },
        {
          "id": "C1-03",
          "zh": "人们为什么把梦想描绘"
        },
        {
          "id": "C1-04",
          "zh": "难道没有答案吗"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "星星为什么在闪耀呢"
        },
        {
          "id": "C1-02",
          "zh": "云儿为什么在天空游荡"
        },
        {
          "id": "C1-03",
          "zh": "人们为什么描绘梦想"
        },
        {
          "id": "C1-04",
          "zh": "难道没有答案吗"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "星星为什么在夜空闪烁"
        },
        {
          "id": "C1-02",
          "zh": "云朵为什么在天空游过"
        },
        {
          "id": "C1-03",
          "zh": "人们为什么把梦想描摹"
        },
        {
          "id": "C1-04",
          "zh": "答案也许没有尽头"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "星星啊 为何 一整夜 眨着眼睛"
        },
        {
          "id": "C1-02",
          "zh": "云朵啊 为何 在天空 游成鱼群"
        },
        {
          "id": "C1-03",
          "zh": "人儿啊 为何 把明天 画成梦境"
        },
        {
          "id": "C1-04",
          "zh": "答案啊 也许 从来就没有"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "星星呀 为何 一整夜 眨着眼睛"
        },
        {
          "id": "C1-02",
          "zh": "云朵呀 怎么 学鱼儿 游过天空"
        },
        {
          "id": "C1-03",
          "zh": "人们呀 为何 总想要 种一个梦"
        },
        {
          "id": "C1-04",
          "zh": "答案呀 也许 吹散在风里"
        }
      ]
    }
  ]
}

